from fastmcp import Client
import asyncio

config = {
    "mcpServers": {
        "__SERVER__": {
            "url": "http://localhost:4000/__SERVER__/mcp",
            "headers": {"x-litellm-api-key": "Bearer sk-1234"},
        }
    }
}

client = Client(config)

async def main():
    async with client:
        tools = await client.list_tools()
        response = await client.call_tool(
            name="tool_name",
            arguments={"arg": "value"},
        )
        print(response)

if __name__ == "__main__":
    asyncio.run(main())
